?>
<?php CommerceController::exportLink($cid,$p); ?>
<section class="erp-card"><h2><?php echo esc_html($titles[$type]); ?></h2><?php self::search($cid,$p); ?><div class="erp-scroll"><table class="erp-table"><thead><tr><?php echo self::sortHead('code','کد').self::sortHead('name','نام'); ?><th><?php echo $type==='tax'?'نرخ/اعتبار/تأیید':'وضعیت'; ?></th><th>عملیات</th></tr></thead><tbody>
<?php foreach($data['rows'] as $row): ?><tr><td><?php echo esc_html($row['code']); ?></td><td><?php echo esc_html($row['name']); ?></td><td><?php if($type==='tax')echo esc_html(($row['bp']===null?'تعیین نشده':Money::toFa((string)intdiv((int)$row['bp'],100).((int)$row['bp']%100?'.'.str_pad((string)((int)$row['bp']%100),2,'0',STR_PAD_LEFT):'')).'٪'). ' / '.Jalali::format($row['valid_from']).' — '.Jalali::format($row['valid_to']).' / '.($row['confirmed']?'تأییدشده':'تأییدنشده'));else echo $row['is_active']?'فعال':'غیرفعال'; ?></td><td><?php if(Ctx::can($type==='tax'?'tax_rate.edit':'item.edit')): ?><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>$p,'edit'=>$row['id']])); ?>">ویرایش</a><?php endif; ?><?php if(Ctx::can($type==='tax'?'tax_rate.edit':'item.delete')): ?><form method="post" class="inline" onsubmit="return confirm('فقط رکورد بدون سابقه حذف می‌شود. ادامه می‌دهید؟')"><?php self::form('module_catalog_delete',$cid,$p,$row['id']); ?><input type="hidden" name="entity" value="<?php echo esc_attr($type); ?>"><button type="submit" class="btn btn-outline btn-sm">حذف بدون سابقه</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($data['pages'],$data['page']); ?></section>
<?php if(Ctx::can($type==='tax'?'tax_rate.edit':($edit?'item.edit':'item.create'))): ?><section class="erp-card"><h3><?php echo esc_html(($edit?'ویرایش ':'افزودن ').$titles[$type]); ?></h3><form method="post" class="erp-form"><?php self::form('module_catalog_save',$cid,$p,$edit); ?><input type="hidden" name="entity" value="<?php echo esc_attr($type); ?>"><?php self::input('code','کد',$r['code']??'','text','required maxlength="'.(in_array($type,['unit','group'],true)?20:30).'" dir="ltr"');self::input('name','نام',$r['name']??'','text','required maxlength="'.($type==='item'?190:100).'"');
if($type==='tax'){
    $bp=(int)($r['bp']??0);$pct=intdiv($bp,100).($bp%100?'.'.str_pad((string)($bp%100),2,'0',STR_PAD_LEFT):'');
    self::input('percent','درصد مالیات (نرخ رسمی را خودتان بازبینی کنید)',$r&&$r['bp']===null?'':$pct,'text','required inputmode="decimal"');self::input('valid_from','از تاریخ شمسی',isset($r['valid_from'])?Jalali::format($r['valid_from'],false):Jalali::format(Jalali::today(),false),'text','required data-jalali dir="ltr"');self::input('valid_to','تا تاریخ شمسی',isset($r['valid_to'])?Jalali::format($r['valid_to'],false):Jalali::format(Jalali::yearRange(Jalali::currentYear())[1],false),'text','required data-jalali dir="ltr"');
    if(Ctx::can('tax_rate.confirm')): ?><label><input type="checkbox" name="confirmed" value="1" <?php checked(self::value('confirmed',$r['confirmed']??0),1); ?>> این نرخ و بازه را بازبینی و تأیید می‌کنم.</label><?php else: ?><p>نرخ ویرایش‌شده تا تأیید کاربر دارای مجوز تأیید نرخ، قابل استفادهٔ مالیاتی نیست.</p><?php endif;
}else{ ?><label><input type="checkbox" name="is_active" value="1" <?php checked(self::value('is_active',$r['is_active']??1),1); ?>>فعال</label><?php }
if($type==='item'){
    self::select('kind','نوع',['goods'=>'کالا','service'=>'خدمت'],$r['kind']??'goods');self::input('barcode','بارکد',$r['barcode']??'','text','maxlength="80"');
    foreach(['unit_id'=>['units','واحد',false],'group_id'=>['item_groups','گروه',true],'tax_rate_id'=>['tax_rates','نرخ مالیات',true]] as $key=>$meta){$options=$meta[2]?[0=>$key==='tax_rate_id'?'غیرمشمول':'بدون گروه']:[];foreach(Db::rows('SELECT id,name FROM '.Db::t($meta[0]).' WHERE company_id=%d ORDER BY id',$cid) as $o)$options[$o['id']]=$o['name'];self::select($key,$meta[1],$options,$r[$key]??0);}
    $accounts=[];foreach(Db::rows('SELECT id,code,name FROM '.Db::t('accounts').' WHERE company_id=%d AND level=3 AND is_active=1 ORDER BY code',$cid) as $o)$accounts[$o['id']]=$o['code'].' — '.$o['name'];
    foreach(['sale_account_id'=>'حساب فروش','purchase_account_id'=>'حساب خرید'] as $key=>$label){$sys=$key==='sale_account_id'?(self::value('kind',$r['kind']??'goods')==='service'?'sales_services':'sales_goods'):(Settings::get('purchase_goods_mode',$cid)==='inventory'?'inventory':'purchases');$default=(int)Db::val('SELECT id FROM '.Db::t('accounts').' WHERE company_id=%d AND sys_key=%s',$cid,$sys);self::select($key,$label,$accounts,$r[$key]??$default);}
    foreach(['sale_price'=>'قیمت فروش','purchase_price'=>'قیمت خرید'] as $key=>$label)self::input($key,$label.' ('.(Ctx::unit()==='rial'?'ریال':'تومان').')',Money::toInputValue((int)($r[$key]??0),Ctx::unit()),'text','required inputmode="decimal"');
    self::input('trade_price','قیمت همکاری برای فروشگاه؛ صفر یعنی ندارد ('.(Ctx::unit()==='rial'?'ریال':'تومان').')',Money::toInputValue((int)($r['trade_price']??0),Ctx::unit()),'text','inputmode="decimal"');
    $attrLines='';foreach((array)json_decode((string)($r['attrs']??''),true) as $ak=>$av)$attrLines.=$ak.'='.$av."\n";
    echo '<label>مشخصات فروشگاهی (هر سطر کلید=مقدار، مثل pairs=12)<textarea name="attrs" rows="4" dir="ltr">'.esc_textarea(self::value('attrs',$attrLines)).'</textarea></label>';
}
?><button type="submit" class="btn btn-primary">ذخیره</button></form></section><?php endif; ?>
